const MAX_NODES = 16;
const MAX_LINKS = 24;
const MIN_CLEARANCE = 10;
export const sat = (x) => Math.max(0, Math.min(1, x));

export function eligibleGraph(graph) {
  return graph.nodes.length >= 2 && graph.nodes.length <= MAX_NODES && graph.links.length <= MAX_LINKS;
}

export function geometry(graph, pos) {
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  let width = 0, height = 0, cy = 0;
  for (const n of graph.nodes) {
    const [x, y] = pos[n.id];
    x0 = Math.min(x0, x);
    y0 = Math.min(y0, y);
    x1 = Math.max(x1, x + n.w);
    y1 = Math.max(y1, y + n.h);
    width += n.w;
    height += n.h;
    cy += y + n.h / 2;
  }
  const count = graph.nodes.length;
  return {width: x1 - x0, height: y1 - y0, w: width / count, h: height / count, cy: cy / count};
}

function layoutFeatures(graph, input, base, original, d) {
  const n = graph.nodes.length, m = graph.links.length;
  const a = geometry(graph, input), b = geometry(graph, base);
  const sources = new Set(), targets = new Set();
  for (const {from, to} of graph.links) {
    sources.add(from);
    targets.add(to);
  }
  return [
    Math.log2(n) / 5,
    sat(m / (n * 2)),
    sources.size / n,
    targets.size / n,
    sat(a.width / (n * a.w)),
    sat(a.height / (n * a.h)),
    sat(a.w / 360),
    sat(a.h / 360),
    sat(original.overlap_pairs / n),
    sat(original.edge_crossings / Math.max(1, m)),
    sat(original.backward_edges / Math.max(1, m)),
    sat(d.edge_crossings / Math.max(1, m)),
    sat(d.displacement_rms / 600),
    sat(d.edge_length_mean / 900),
    sat(b.width / (n * b.w)),
    sat(b.height / (n * b.h))
  ];
}

export function layoutObservation(graph, engine, baseline, initialStats = engine.layoutMetrics(graph, baseline)) {
  const input = Object.fromEntries(graph.nodes.map((n) => [n.id, [n.x, n.y]]));
  const originalStats = engine.layoutMetrics(graph, input);
  return {
    graph,
    engine,
    input,
    baseline,
    initialStats,
    features: layoutFeatures(graph, input, baseline, originalStats, initialStats),
  };
}

export function forwardWires(graph, positions) {
  const byId = new Map(graph.nodes.map((n) => [n.id, n]));
  return graph.links.every(({from, to}) =>
    positions[to][0] - positions[from][0] - byId.get(from).w >= MIN_CLEARANCE);
}

export function rankLayout(graph, engine, pos) {
  const stats = engine.layoutMetrics(graph, pos);
  const forward = forwardWires(graph, pos);
  return {stats, valid: stats.overlap_pairs === 0 && forward};
}

function dense(input, {weights, bias}) {
  return weights.map((row, i) => row.reduce((sum, w, j) => sum + w * input[j], bias[i]));
}

export function predictControls(features, model) {
  return model.latents.map((latent) => {
    const input = features.concat(latent);
    const l1 = dense(input, model.layers[0]).map((x) => Math.max(x, 0.2 * x));
    const l2 = dense(l1, model.layers[1]).map((x) => Math.max(x, 0.2 * x));
    return dense(l2, model.layers[2]).map((x) => 1 / (1 + Math.exp(-x)));
  });
}



const MIN_GAP = 8;

function groupSwappableColumns(graph, baseline) {
  const byX = new Map();
  for (const node of graph.nodes) {
    const x = baseline[node.id][0];
    if (!byX.has(x)) byX.set(x, []);
    byX.get(x).push(node);
  }
  return [...byX].sort(([a], [b]) => a - b).map(([, nodes]) =>
    nodes.sort((a, b) => baseline[a.id][1] - baseline[b.id][1] || a.id.localeCompare(b.id))
  ).filter((nodes) => nodes.length > 1);
}

function segmentHitsBox(x0, y0, x1, y1, box) {
  const [left, top, right, bottom] = box;
  if (Math.max(x0, x1) <= left || Math.min(x0, x1) >= right ||
      Math.max(y0, y1) <= top || Math.min(y0, y1) >= bottom) return false;
  let low = 0, high = 1;
  for (const [a, b, min, max] of [[x0, x1, left, right], [y0, y1, top, bottom]]) {
    if (a === b) {
      if (a <= min || a >= max) return false;
    } else {
      const u = (min - a) / (b - a), v = (max - a) / (b - a);
      low = Math.max(low, Math.min(u, v));
      high = Math.min(high, Math.max(u, v));
      if (low >= high) return false;
    }
  }
  return true;
}

export function cableOcclusions(graph, positions) {
  const nodes = new Map(graph.nodes.map((n) => [n.id, n]));
  let occluded = 0;
  for (const {from, to} of graph.links) {
    const a = nodes.get(from), b = nodes.get(to);
    const [ax, ay] = positions[from], [bx, by] = positions[to];
    const sx = ax + a.w, sy = ay + a.h / 2, tx = bx, ty = by + b.h / 2;
    const bend = Math.max(42, Math.abs(tx - sx) * 0.45);
    const points = [[sx, sy]];
    for (let i = 1; i <= 14; i++) {
      const t = i / 14, u = 1 - t;
      points.push([u ** 3 * sx + 3 * u * u * t * (sx + bend) +
                   3 * u * t * t * (tx - bend) + t ** 3 * tx,
                   u ** 3 * sy + 3 * u * u * t * sy + 3 * u * t * t * ty + t ** 3 * ty]);
    }
    for (const n of graph.nodes) {
      if (n.id === from || n.id === to) continue;
      const [x, y] = positions[n.id], box = [x + 1, y + 1, x + n.w - 1, y + n.h - 1];
      if (Math.max(sy, ty) <= box[1] || Math.min(sy, ty) >= box[3]) continue;
      for (let i = 1; i < points.length; i++) {
        if (segmentHitsBox(...points[i - 1], ...points[i], box)) {
          occluded++;
          break;
        }
      }
    }
  }
  return occluded;
}

export function crossingContext(graph, engine, baseline, initialStats) {
  const observation = layoutObservation(graph, engine, baseline, initialStats);
  const columns = groupSwappableColumns(graph, baseline);
  return {...observation, columns, occlusions: cableOcclusions(graph, baseline)};
}

const choose = (input, count) => Math.min(count - 1, Math.floor(input * count));

export function proposeCrossingSwap(context, action) {
  const {baseline, columns} = context;
  if (!columns.length) return null;
  const column = columns[choose(action[0], columns.length)];
  const left = choose(action[1], column.length);
  const right = choose(action[2], column.length - 1);
  const [i, j] = [left, right >= left ? right + 1 : right].sort((a, b) => a - b);
  const [a, b] = [column[i], column[j]];
  const positions = {...baseline};
  if (action[3] < 0.5) {
    positions[a.id] = [baseline[a.id][0], baseline[b.id][1] + (b.h - a.h) / 2];
    positions[b.id] = [baseline[b.id][0], baseline[a.id][1] + (a.h - b.h) / 2];
  } else {
    const ordered = column.slice(i, j + 1);
    [ordered[0], ordered[ordered.length - 1]] = [ordered.at(-1), ordered[0]];
    let y = baseline[a.id][1];
    for (const [offset, card] of ordered.entries()) {
      positions[card.id] = [baseline[card.id][0], Math.round(y * 10) / 10];
      if (offset === ordered.length - 1) break;
      const prev = column[i + offset], next = column[i + offset + 1];
      y += card.h + baseline[next.id][1] - baseline[prev.id][1] - prev.h;
    }
  }
  const sorted = column.slice().sort((x, y) => positions[x.id][1] - positions[y.id][1]);
  for (let k = 1; k < sorted.length; k++) {
    const prev = sorted[k - 1], next = sorted[k];
    if (positions[next.id][1] - positions[prev.id][1] - prev.h < MIN_GAP - 0.1) return null;
  }
  return positions;
}

export function scoreCrossingSwap(context, positions) {
  if (!positions) return null;
  const {graph, engine, baseline, initialStats, occlusions} = context;
  const {valid, stats} = rankLayout(graph, engine, positions);
  const crossingsRemoved = initialStats.edge_crossings - stats.edge_crossings;
  if (!valid || crossingsRemoved < 1 || stats.bounds_height > initialStats.bounds_height + 0.51 ||
      stats.edge_length_mean > initialStats.edge_length_mean * 1.08 + 0.01) return null;
  const afterOcclusions = cableOcclusions(graph, positions);
  if (afterOcclusions > occlusions) return null;
  const shift = graph.nodes.reduce((sum, {id}) => sum + Math.abs(positions[id][1] - baseline[id][1]), 0) /
    graph.nodes.length;
  const score = crossingsRemoved + 0.03 * (occlusions - afterOcclusions) -
    0.10 * Math.min(1, shift / 160);
  return {stats, shift, score, crossingsRemoved, occlusions: afterOcclusions};
}

export function selectCrossingSwap(context, actions) {
  let best = {positions: context.baseline, stats: context.initialStats, shift: 0, score: 0,
    crossingsRemoved: 0, occlusions: context.occlusions, picked: -1};
  if (!context.initialStats.edge_crossings || !context.columns.length) return best;
  for (let i = 0; i < actions.length; i++) {
    const a = actions[i];
    if (!Array.isArray(a) || a.length !== 4 || a.some((x) => !Number.isFinite(x) || x < 0 || x > 1)) continue;
    const positions = proposeCrossingSwap(context, a);
    const result = scoreCrossingSwap(context, positions);
    if (result && result.score > best.score + 1e-8) best = {...result, positions, picked: i};
  }
  return best;
}

export function arrangeParticleCrossingLayout(graph, engine, baseline, model) {
  if (!model || !eligibleGraph(graph) || graph.links.length < 2) return baseline;
  const initialStats = engine.layoutMetrics(graph, baseline);
  if (!initialStats.edge_crossings) return baseline;
  const context = crossingContext(graph, engine, baseline, initialStats);
  return selectCrossingSwap(context, predictControls(context.features, model)).positions;
}

export function swapActions(context) {
  const actions = [];
  const columnCount = context.columns.length;
  for (const [c, column] of context.columns.entries()) {
    for (let i = 0; i < column.length - 1; i++) {
      for (let j = i + 1; j < column.length; j++) {
        for (const mode of [0.25, 0.75]) {
          actions.push([(c + 0.5) / columnCount, (i + 0.5) / column.length,
            (j - 0.5) / (column.length - 1), mode]);
        }
      }
    }
  }
  return actions;
}


export const PROPOSAL_BUDGET = 8;
export const FEATURE_COUNT = 22;
const COMPOUND_SEEDS = 12;

function orient(a, b, c) {
  const value = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);
  return Math.abs(value) < 1e-9 ? 0 : Math.sign(value);
}

function segmentsCross(a, b, c, d) {
  return orient(a, b, c) * orient(a, b, d) < 0 && orient(c, d, a) * orient(c, d, b) < 0;
}

function entersBox(a, b, box) {
  let start = 0, end = 1;
  for (let axis = 0; axis < 2; axis++) {
    const dz = b[axis] - a[axis];
    const min = box[axis], max = box[axis + 2];
    if (Math.min(a[axis], b[axis]) >= max || Math.max(a[axis], b[axis]) <= min) return false;
    if (dz === 0) continue;
    const u = (min - a[axis]) / dz, v = (max - a[axis]) / dz;
    start = Math.max(start, Math.min(u, v));
    end = Math.min(end, Math.max(u, v));
    if (start >= end) return false;
  }
  return true;
}

function wireShape(positions, from, to) {
  const x0 = positions[from.id][0] + from.w;
  const y0 = positions[from.id][1] + from.h / 2;
  const x1 = positions[to.id][0];
  const y1 = positions[to.id][1] + to.h / 2;
  const bend = Math.max(42, Math.abs(x1 - x0) * 0.45);
  const points = [[x0, y0]];
  for (const t of [0.25, 0.5, 0.75]) {
    const u = 1 - t;
    const blend = 3 * t * t * u + t * t * t;
    points.push([x0 + (x1 - x0) * blend + 3 * t * u * (u - t) * bend, y0 + (y1 - y0) * blend]);
  }
  points.push([x1, y1]);
  const xs = points.map(p => p[0]);
  const bounds = [Math.min(...xs), Math.min(y0, y1), Math.max(...xs), Math.max(y0, y1)];
  let length = 0;
  for (let i = 1; i < points.length; i++) length += Math.hypot(points[i][0] - points[i - 1][0], points[i][1] - points[i - 1][1]);
  return {points, bounds, length};
}

function shapesIntersect(a, b) {
  const x = a.bounds, y = b.bounds;
  if (x[0] > y[2] || y[0] > x[2] || x[1] > y[3] || y[1] > x[3]) return false;
  for (let i = 1; i < a.points.length; i++) {
    for (let j = 1; j < b.points.length; j++) {
      if (segmentsCross(a.points[i - 1], a.points[i], b.points[j - 1], b.points[j])) return true;
    }
  }
  return false;
}

function coarseMetrics(context, positions) {
  const {graph, linkNodes, wirePairs} = context;
  const edges = linkNodes.map(([from, to]) => wireShape(positions, from, to));
  const flags = [];
  let coarse = 0, straight = 0, blocked = 0, deviation = 0;
  for (const [i, j] of wirePairs) {
    const a = edges[i], b = edges[j];
    const crosses = shapesIntersect(a, b);
    flags.push(crosses);
    coarse += Number(crosses);
    straight += Number(segmentsCross(a.points[0], a.points.at(-1), b.points[0], b.points.at(-1)));
  }
  graph.nodes.forEach(({id, w, h}) => {
    const [x, y] = positions[id];
    const box = [x + 1, y + 1, x + w - 1, y + h - 1];
    edges.forEach(({points, bounds}, index) => {
      if (linkNodes[index][0].id === id || linkNodes[index][1].id === id || bounds[0] >= box[2] ||
          bounds[2] <= box[0] || bounds[1] >= box[3] || bounds[3] <= box[1]) return;
      for (let j = 1; j < points.length; j++) {
        if (entersBox(points[j - 1], points[j], box)) { blocked++; break; }
      }
    });
  });
  let length = 0;
  for (const edge of edges) {
    length += edge.length;
    deviation += Math.abs(edge.points[0][1] - edge.points.at(-1)[1]);
  }
  return {coarse, straight, blocked, length, deviation, flags};
}

function actionFeatures(context, candidate, action, before, after) {
  const {graph, baseline, initialStats, occlusions} = context;
  let gained = 0, lost = 0;
  before.flags.forEach((flag, index) => {
    if (flag && !after.flags[index]) gained++;
    if (!flag && after.flags[index]) lost++;
  });
  let moved = 0, maxMove = 0, totalMove = 0, minY = Infinity, maxY = -Infinity;
  for (const {id, h} of graph.nodes) {
    const y = candidate[id][1];
    const shift = Math.abs(y - baseline[id][1]);
    if (shift > 0.01) moved++;
    maxMove = Math.max(maxMove, shift);
    totalMove += shift;
    minY = Math.min(minY, y);
    maxY = Math.max(maxY, y + h);
  }
  const bound = x => Math.tanh(x);
  const linkCount = graph.links.length;
  return [
    bound((before.coarse - after.coarse) / 4),
    bound((before.straight - after.straight) / 4),
    bound((before.blocked - after.blocked) / 3),
    bound((before.length - after.length) / (150 * linkCount)),
    bound((before.deviation - after.deviation) / (150 * linkCount)),
    bound(gained / 4), bound(lost / 4), bound(before.coarse / 12), bound(after.coarse / 12),
    bound((initialStats.edge_crossings - before.coarse) / 4),
    bound((occlusions - before.blocked) / 3),
    bound((maxY - minY - initialStats.bounds_height) / 50),
    bound(totalMove / 1000), bound(maxMove / 650), moved / graph.nodes.length,
    graph.nodes.length / 16, linkCount / 24, action[3],
    bound(before.blocked / 12), bound(after.blocked / 12),
    bound(initialStats.edge_crossings / 12), bound(context.columns.length / 4),
  ];
}

function rotatedTriples({columns, baseline}) {
  const rotations = [];
  for (const column of columns) {
    for (let i = 0; i + 2 < column.length; i++) {
      const source = column.slice(i, i + 3);
      const top = baseline[source[0].id][1];
      const gaps = source.slice(1).map((next, index) =>
        baseline[next.id][1] - baseline[source[index].id][1] - source[index].h);
      if (gaps.some(gap => gap < 7.9)) continue;
      for (const shift of [1, 2]) {
        const order = source.slice(shift).concat(source.slice(0, shift));
        const positions = {...baseline};
        let y = top;
        for (const [index, card] of order.entries()) {
          positions[card.id] = [baseline[card.id][0], Math.round(y * 10) / 10];
          if (index < gaps.length) y += card.h + gaps[index];
        }
        rotations.push(positions);
      }
    }
  }
  return rotations;
}

export function prepareRankedSwaps(graph, engine, baseline, expanded = false) {
  if (!eligibleGraph(graph) || graph.links.length < 2 || !forwardWires(graph, baseline)) return null;
  const initial = engine.layoutMetrics(graph, baseline);
  if (!initial.edge_crossings) return null;
  const context = crossingContext(graph, engine, baseline, initial);
  const actions = swapActions(context);
  if (!actions.length) return null;
  const byId = new Map(graph.nodes.map(node => [node.id, node]));
  const linkNodes = graph.links.map(({from, to}) => [byId.get(from), byId.get(to)]);
  const wirePairs = [];
  linkNodes.forEach(([a, b], i) => {
    for (let j = i + 1; j < linkNodes.length; j++) {
      const [c, d] = linkNodes[j];
      if (a !== c && a !== d && b !== c && b !== d) wirePairs.push([i, j]);
    }
  });
  Object.assign(context, {linkNodes, wirePairs});
  const before = coarseMetrics(context, baseline);
  const seen = new Set();
  const candidates = [];
  const add = (positions, mode, index) => {
    if (!positions) return;
    const key = graph.nodes.map(({id}) => Math.round(positions[id][1] * 1000)).join(',');
    if (seen.has(key)) return;
    seen.add(key);
    const after = coarseMetrics(context, positions);
    const features = actionFeatures(context, positions, [0, 0, 0, mode], before, after);
    const heuristic = before.coarse - after.coarse + 0.18 * (before.straight - after.straight)
      + 0.08 * Math.max(0, before.blocked - after.blocked) - 0.8 * Math.max(0, after.blocked - before.blocked)
      - 0.2 * Math.max(0, features[11]) - 0.05 * features[12];
    candidates.push({index, positions, features, heuristic});
  };
  for (const [index, action] of actions.entries()) add(proposeCrossingSwap(context, action), action[3], index);
  if (expanded) {
    let index = actions.length;
    const seeds = candidates.slice().sort((a, b) => b.heuristic - a.heuristic || a.index - b.index)
      .slice(0, COMPOUND_SEEDS).map(({positions}) => {
        const moved = graph.nodes.filter(({id}) => positions[id][1] !== baseline[id][1]);
        return {positions, moved, x: baseline[moved[0].id][0]};
      });
    for (const positions of rotatedTriples(context)) add(positions, 0, index++);
    for (let i = 0; i < seeds.length; i++) {
      for (let j = i + 1; j < seeds.length; j++) {
        const a = seeds[i], b = seeds[j];
        if (a.x === b.x) continue;
        const combined = {...baseline};
        for (const {id} of a.moved) combined[id] = a.positions[id];
        for (const {id} of b.moved) combined[id] = b.positions[id];
        add(combined, 1, index++);
      }
    }
  }
  return {context, actions, candidates};
}

export function selectRankedSwaps(prepared, rank, budget = PROPOSAL_BUDGET) {
  const {context, candidates} = prepared;
  const ordered = candidates.map(candidate => ({candidate, rank: rank(candidate)}))
    .sort((a, b) => b.rank - a.rank || a.candidate.index - b.candidate.index);
  let best = null;
  for (const {candidate} of ordered.slice(0, budget)) {
    const outcome = scoreCrossingSwap(context, candidate.positions);
    if (outcome && (!best || outcome.score > best.score + 1e-8)) {
      best = {...outcome, positions: candidate.positions, index: candidate.index};
    }
  }
  return {best, evaluated: Math.min(budget, ordered.length)};
}

export function learnedScore(candidate, model) {
  const predictions = predictControls(candidate.features, model);
  return predictions.reduce((sum, [quality]) => sum + quality, 0) / predictions.length;
}

function arrangeRankedParticleLayout(graph, engine, baseline, model) {
  if (!model) return baseline;
  const prepared = prepareRankedSwaps(graph, engine, baseline, model.expanded === true);
  if (!prepared) return baseline;
  return selectRankedSwaps(prepared, candidate => learnedScore(candidate, model)).best?.positions ?? baseline;
}

